def get_leftmost_2_in_row(r, grid):
    """Get the leftmost column index with a 2 in row r"""
    for c in range(len(grid[0])):
        if grid[r][c] == 2:
            return c
    return None

def get_rightmost_2_in_row(r, grid):
    """Get the rightmost column index with a 2 in row r"""
    for c in range(len(grid[0]) - 1, -1, -1):
        if grid[r][c] == 2:
